DEFAULT_TIMEOUT_SECONDS = 3600


def _to_int(value, default):
    try:
        return int(value)
    except Exception:
        return int(default)


def _to_float(value, default):
    try:
        return float(value)
    except Exception:
        return float(default)


def _is_nonempty_str(value):
    return isinstance(value, str) and bool(value.strip())


def normalize_messages_bedrock(messages):
    normalized = []
    if not isinstance(messages, list):
        return normalized
    for message in messages:
        if not isinstance(message, dict):
            message = {}
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({"role": role, "content": [{"type": "text", "text": content}]})
            continue
        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append({"type": "text", "text": item["text"]})
                    continue
                if isinstance(item, str):
                    parts.append({"type": "text", "text": item})
                    continue
            if not parts:
                parts.append({"type": "text", "text": ""})
            normalized.append({"role": role, "content": parts})
            continue
        normalized.append({"role": role, "content": [{"type": "text", "text": str(content)}]})
    return normalized


def normalize_messages_openai(messages):
    normalized = []
    if not isinstance(messages, list):
        return normalized
    for message in messages:
        if not isinstance(message, dict):
            message = {}
        role = str(message.get("role", "user")).strip() or "user"
        content = message.get("content", "")
        if isinstance(content, str):
            normalized.append({"role": role, "content": content})
            continue
        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict) and item.get("type") == "text" and isinstance(item.get("text"), str):
                    parts.append(item["text"])
                    continue
                if isinstance(item, str):
                    parts.append(item)
                    continue
            normalized.append({"role": role, "content": " ".join(parts).strip()})
            continue
        normalized.append({"role": role, "content": str(content)})
    return normalized


def _http_post_json(host, path, payload_json_str, headers, timeout):
    connection = http.client.HTTPSConnection(host, timeout=timeout)
    try:
        connection.request("POST", path, body=payload_json_str, headers=headers)
        response = connection.getresponse()
        status = response.status
        raw_bytes = response.read()
        content_type = response.getheader("Content-Type", "")
        return status, raw_bytes, content_type
    finally:
        try:
            connection.close()
        except Exception:
            pass


def invoke_bedrock(
    messages,
    system=None,
    max_tokens=4096,
    temperature=0.7,
    top_p=None,
    stop_sequences=None,
    region=None,
    model_id=None,
    api_key=None,
    timeout=DEFAULT_TIMEOUT_SECONDS,
):
    if not _is_nonempty_str(api_key):
        return {"ok": False, "status": 500, "error": {"message": "Missing AWS_BEARER_TOKEN_BEDROCK"}}
    if not _is_nonempty_str(region):
        region = "us-east-1"
    if not _is_nonempty_str(model_id):
        model_id = BEDROCK_DEFAULT_MODEL_ID
    max_tokens_int = _to_int(max_tokens, 4096)
    if max_tokens_int < 1:
        max_tokens_int = 1
    if max_tokens_int > BEDROCK_MAX_TOKENS_LIMIT:
        max_tokens_int = BEDROCK_MAX_TOKENS_LIMIT
    host = "bedrock-runtime." + region + ".amazonaws.com"
    model_id_encoded = urllib.parse.quote(model_id, safe="")
    path = "/model/" + model_id_encoded + "/invoke"
    body = {
        "anthropic_version": "bedrock-2023-05-31",
        "max_tokens": max_tokens_int,
        "messages": normalize_messages_bedrock(messages),
    }
    if _is_nonempty_str(system):
        body["system"] = system
    if temperature is not None:
        body["temperature"] = _to_float(temperature, 0.7)
    if top_p is not None:
        body["top_p"] = _to_float(top_p, 1.0)
    if isinstance(stop_sequences, list) and len(stop_sequences) > 0:
        body["stop_sequences"] = stop_sequences
    payload = json.dumps(body, ensure_ascii=False).encode("utf-8")
    headers = {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "Authorization": "Bearer " + api_key,
    }
    try:
        status, raw_bytes, content_type = _http_post_json(host, path, payload, headers, timeout)
    except Exception as e:
        return {"ok": False, "status": 502, "error": {"message": "Bedrock request failed", "detail": str(e)}}
    if status != 200:
        try:
            error_body = json.loads(raw_bytes.decode("utf-8"))
        except Exception:
            error_body = {"message": raw_bytes.decode("utf-8", errors="ignore")}
        return {"ok": False, "status": status, "error": error_body}
    if isinstance(content_type, str) and "application/json" in content_type:
        try:
            parsed = json.loads(raw_bytes.decode("utf-8"))
            return {"ok": True, "data": parsed}
        except Exception:
            return {"ok": True, "data": {"raw": raw_bytes.decode("utf-8", errors="ignore")}}
    return {"ok": True, "data": {"raw": raw_bytes.decode("utf-8", errors="ignore")}}


