        messages=messages,
        system=system,
        max_tokens=bedrock_max_tokens,
        temperature=temperature,
        top_p=top_p,
        stop_sequences=stop_sequences,
        region=region,
        model_id=bedrock_model_id,
        api_key=bedrock_api_key,
        timeout=timeout,
    )
    if not bedrock_result.get("ok"):
        status = _to_int(bedrock_result.get("status", 500), 500)
        return jsonify({"error": bedrock_result.get("error"), "status": status, "provider": "bedrock"}), status
    bedrock_text, bedrock_usage = extract_text_from_bedrock(bedrock_result.get("data"))

