        messages=messages,
        model=grok_41_model_id,
        max_tokens=grok_41_max_tokens,
        temperature=temperature,
        top_p=top_p,
        api_key=xai_api_key,
        timeout=timeout,
    )
    if not grok_41_result.get("ok"):
        status = _to_int(grok_41_result.get("status", 500), 500)
        return jsonify({"error": grok_41_result.get("error"), "status": status, "provider": "xai", "model": grok_41_model_id}), status
    grok_41_text, grok_41_usage = extract_text_from_grok(grok_41_result.get("data"))

    grok_4_result = invoke_grok(
        messages=messages,
        model=grok_4_model_id,
        max_tokens=grok_4_max_tokens,
        temperature=temperature,
        top_p=top_p,
        api_key=xai_api_key,
        timeout=timeout,
    )
    if not grok_4_result.get("ok"):
        status = _to_int(grok_4_result.get("status", 500), 500)
        return jsonify({"error": grok_4_result.get("error"), "status": status, "provider": "xai", "model": grok_4_model_id}), status
    grok_4_text, grok_4_usage = extract_text_from_grok(grok_4_result.get("data"))

