    if synthesis_enabled is None:
        synthesis_enabled = True
    synthesis_enabled = bool(synthesis_enabled)

    if not synthesis_enabled:
        return jsonify(
            {
                "output_text": "",
                "models": {
                    "bedrock": {"model_id": bedrock_model_id, "region": region, "text": bedrock_text, "usage": bedrock_usage},
                    "grok_4_1": {"model_id": grok_41_model_id, "text": grok_41_text, "usage": grok_41_usage},
                    "grok_4": {"model_id": grok_4_model_id, "text": grok_4_text, "usage": grok_4_usage},
                },
                "synthesis": {"enabled": False},
            }
        )

    synthesis_temperature = payload.get("synthesis_temperature", 0.2)
    synthesis_top_p = payload.get("synthesis_top_p")
    synthesis_stop_sequences = payload.get("synthesis_stop_sequences")
    synthesis_max_tokens = _to_int(payload.get("synthesis_max_tokens", BEDROCK_MAX_TOKENS_LIMIT), BEDROCK_MAX_TOKENS_LIMIT)
    if synthesis_max_tokens < 1:
        synthesis_max_tokens = 1
    if synthesis_max_tokens > BEDROCK_MAX_TOKENS_LIMIT:
        synthesis_max_tokens = BEDROCK_MAX_TOKENS_LIMIT

    synthesis_system = ""
    if _is_nonempty_str(system):
        synthesis_system = system.strip()

    synthesis_prompt = build_synthesis_prompt(messages, bedrock_text, grok_41_text, grok_4_text)
    synthesis_messages = [{"role": "user", "content": synthesis_prompt}]

    synthesis_result = invoke_bedrock(
        messages=synthesis_messages,
        system=synthesis_system,
        max_tokens=synthesis_max_tokens,
        temperature=synthesis_temperature,
        top_p=synthesis_top_p,
        stop_sequences=synthesis_stop_sequences,
        region=region,
        model_id=bedrock_model_id,
        api_key=bedrock_api_key,
        timeout=timeout,
    )
    if not synthesis_result.get("ok"):
        status = _to_int(synthesis_result.get("status", 500), 500)
        return jsonify({"error": synthesis_result.get("error"), "status": status, "provider": "bedrock", "stage": "synthesis"}), status

    synthesis_text, synthesis_usage = extract_text_from_bedrock(synthesis_result.get("data"))

    return jsonify(
        {
            "output_text": synthesis_text,
            "models": {
                "bedrock": {"model_id": bedrock_model_id, "region": region, "text": bedrock_text, "usage": bedrock_usage},
                "grok_4_1": {"model_id": grok_41_model_id, "text": grok_41_text, "usage": grok_41_usage},
                "grok_4": {"model_id": grok_4_model_id, "text": grok_4_text, "usage": grok_4_usage},
            },
            "synthesis": {"enabled": True, "provider": "bedrock", "model_id": bedrock_model_id, "usage": synthesis_usage},
        }
    )


if __name__ == "__main__":
    port = _to_int(os.environ.get("PORT", "8000"), 8000)
    app.run(host="0.0.0.0", port=port)

